<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Response\QuestionInteractionResponseDto;use App\Application\QuestionLearning\Mapper\QuestionInteractionResponseMapper;use App\Application\QuestionLearning\Mapper\QuestionNoteResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\UserQuestionInteraction;use App\Domain\QuestionLearning\Repository\QuestionCommentRepositoryInterface;use App\Domain\QuestionLearning\Repository\QuestionNoteRepositoryInterface;use App\Domain\QuestionLearning\Repository\QuestionProblemReportRepositoryInterface;use App\Domain\QuestionLearning\Repository\UserQuestionInteractionRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\QuestionInteractionState;
final readonly class GetQuestionInteractionService { public function __construct(private FrozenQuestionReaderInterface $questions, private UserQuestionInteractionRepositoryInterface $interactions, private QuestionNoteRepositoryInterface $notes, private QuestionCommentRepositoryInterface $comments, private QuestionProblemReportRepositoryInterface $reports, private QuestionInteractionResponseMapper $mapper, private QuestionNoteResponseMapper $noteMapper) {} public function execute(string $userId, string $questionId): QuestionInteractionResponseDto { if (count($this->questions->findByIds([$questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } $interaction = $this->interactions->find($userId, $questionId) ?? new UserQuestionInteraction($userId, $questionId, new QuestionInteractionState(false, false, false), new \DateTimeImmutable(), new \DateTimeImmutable()); $note = $this->notes->findForUserQuestion($userId, $questionId); return $this->mapper->toResponse($interaction, $note === null ? null : $this->noteMapper->toResponse($note), $this->comments->countForQuestion($questionId), $this->reports->countOpenForUserQuestion($userId, $questionId)); } }
